mapper.select:
SELECT id
FROM tb_ai_log_management_operation
WHERE id = #{operationId}
  AND status = 'RUNNING'
  AND execution_token = #{executionToken}
  AND lease_until > #{now}
FOR UPDATE

mapper.update:
UPDATE tb_ai_log_management_operation
SET lease_until = #{leaseUntil},
    update_time = #{now}
WHERE id = #{operationId}
  AND status = 'RUNNING'
  AND execution_token = #{executionToken}

UPDATE tb_ai_log_management_operation
SET execution_token = NULL,
    lease_until = #{now},
    result_json = #{resultJson},
    update_time = #{now}
WHERE id = #{operationId}
  AND status = 'RUNNING'
  AND execution_token = #{executionToken}
